        n = len(s)
        m = 3 - (any(c.islower() for c in s) + any(c.isupper() for c in s) + any(c.isdigit() for c in s))
        runs, i = [], 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if j - i >= 3:
                runs.append(j - i)
            i = j
        if n < 6:
            return max(m, 6 - n)
        rep = sum(L // 3 for L in runs)
        if n <= 20:
            return max(m, rep)
        d = n - 20
        rem = d
        for k in range(3):
            for idx in range(len(runs)):
                if rem <= 0:
                    break
                L = runs[idx]
                if L >= 3 and L % 3 == k:
                    chunk = 1 if k == 0 else (2 if k == 1 else 3)
                    dec = min(rem, chunk)
                    rep -= dec // 3
                    rem -= dec
        return d + max(m, rep)

