import java.util.PriorityQueue;

class Solution {
    public int strongPasswordChecker(String s) {
        int n = s.length();
        boolean lo = false, up = false, di = false;
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) lo = true;
            else if (Character.isUpperCase(c)) up = true;
            else if (Character.isDigit(c)) di = true;
        }
        int m = 3 - ((lo ? 1 : 0) + (up ? 1 : 0) + (di ? 1 : 0));
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int rep = 0, i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            if (j - i >= 3) { pq.offer(new int[]{(j - i) % 3, j - i}); rep += (j - i) / 3; }
            i = j;
        }
        if (n < 6) return Math.max(m, 6 - n);
        if (n <= 20) return Math.max(m, rep);
        int d = n - 20, orig = d;
        while (d > 0 && !pq.isEmpty()) {
            int[] top = pq.poll();
            int chunk = top[0] == 0 ? 1 : (top[0] == 1 ? 2 : 3);
            int dec = Math.min(d, chunk);
            rep -= dec / 3;
            d -= dec;
        }
        return orig + Math.max(m, rep);
    }
}

