        while (j < n && s[j] === s[i]) j++;
        if (j - i >= 3) { heap.push([(j - i) % 3, j - i]); rep += Math.floor((j - i) / 3); }
        i = j;
    }
    if (n < 6) return Math.max(m, 6 - n);
    if (n <= 20) return Math.max(m, rep);
    heap.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    let d = n - 20;
